variante_1.css:
.sl-timeline {
  position: relative;
  padding-left: 20px;
  margin: 0 auto;
}

.sl-timeline-line {
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  width: 4px;
  background-color: var(--sl-border);
  z-index: 1;
}

.sl-timeline-item {
  position: relative;
  margin-bottom: 30px;
  padding-left: 30px;
  z-index: 2;
}

.sl-timeline-point {
  position: absolute;
  left: -8px;
  top: 0;
  width: 20px;
  height: 20px;
  border-radius: 50%;
  background-color: var(--sl-primary);
  border: 4px solid var(--sl-bg-body);
  z-index: 3;
}

.sl-timeline-content {
  margin-left: 0;
  width: 100%;
}

/* Reveal on scroll styles */
.sl-timeline-item-hidden {
  opacity: 0;
  transform: translateY(20px);
  transition: opacity 0.6s ease-out, transform 0.6s ease-out;
}

.sl-timeline-item-visible {
  opacity: 1;
  transform: translateY(0);
}

@media (min-width: 768px) {
  .sl-timeline {
    padding-left: 0;
  }

  .sl-timeline-line {
    left: 50%;
    transform: translateX(-50%);
  }

  .sl-timeline-item {
    width: 50%;
    padding-left: 0;
    clear: both;
  }

  .sl-timeline-item-left {
    float: left;
    text-align: right;
  }

  .sl-timeline-item-right {
    float: right;
    text-align: left;
  }

  .sl-timeline-item-left .sl-timeline-point {
    left: 100%;
    transform: translateX(-50%);
  }

  .sl-timeline-item-right .sl-timeline-point {
    left: 0;
    transform: translateX(-50%);
  }

  .sl-timeline-item-left .sl-timeline-content {
    margin-right: 30px;
    margin-left: 0;
  }

  .sl-timeline-item-right .sl-timeline-content {
    margin-left: 30px;
    margin-right: 0;
  }
}

variante_1.js:
document.addEventListener('DOMContentLoaded', () => {
  const timelineItems = document.querySelectorAll('.sl-timeline-item');

  const observer = new IntersectionObserver((entries, observer) => {
    entries.forEach(entry => {
      if (entry.isIntersecting) {
        entry.target.classList.remove('sl-timeline-item-hidden');
        entry.target.classList.add('sl-timeline-item-visible');
        observer.unobserve(entry.target);
      }
    });
  }, {
    threshold: 0.2
  });

  timelineItems.forEach(item => {
    observer.observe(item);
  });
});

variante_2.css:
.sl-app-timeline {
  position: relative;
  padding-left: 20px;
}

.sl-app-timeline::before {
  content: '';
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  width: 4px;
  background-color: var(--sl-border);
  border-radius: 2px;
}

.sl-app-timeline-item {
  position: relative;
  margin-left: 15px;
}

.sl-app-timeline-item::before {
  content: '';
  position: absolute;
  left: -27px;
  top: 15px;
  width: 14px;
  height: 14px;
  border-radius: 50%;
  background-color: var(--sl-primary);
  border: 3px solid var(--sl-bg-body);
  z-index: 1;
}

.sl-app-timeline-item ul {
  padding-left: 0;
}

.sl-app-timeline-item ul li {
  margin-bottom: 5px;
}

.sl-app-timeline-item ul li:last-child {
  margin-bottom: 0;
}

variante_3.css:
.sl-sidebar-timeline {
  position: relative;
  padding-left: 20px;
}

.sl-sidebar-timeline::before {
  content: '';
  position: absolute;
  left: 20px;
  top: 0;
  bottom: 0;
  width: 2px;
  background-color: var(--sl-border);
  border-radius: 1px;
}

.sl-sidebar-timeline-item {
  position: relative;
  margin-left: 0;
}

.sl-sidebar-timeline-point {
  position: relative;
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background-color: var(--sl-primary);
  border: 2px solid var(--sl-bg-body);
  flex-shrink: 0;
  margin-top: 4px; /* Align with text baseline */
  z-index: 1;
}

.sl-sidebar-timeline-item a {
  font-size: 0.9rem;
  line-height: 1.2;
}

.sl-sidebar-timeline-item small {
  font-size: 0.75rem;
  line-height: 1;
}

variante_4.css:
.sl-horizontal-timeline-wrapper {
  overflow-x: auto;
  padding-bottom: 10px; /* Space for scrollbar */
}

.sl-horizontal-timeline {
  white-space: nowrap;
  position: relative;
  padding-top: 20px;
}

.sl-horizontal-timeline::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 4px;
  background-color: var(--sl-border);
  z-index: 1;
}

.sl-horizontal-timeline-item {
  width: 280px; /* Fixed width for each card */
  max-width: 80vw;
  height: auto;
  position: relative;
  top: 15px; /* Position below the line */
  z-index: 2;
}

.sl-horizontal-timeline-item::before {
  content: '';
  position: absolute;
  top: -25px; /* Position on the line */
  left: 50%;
  transform: translateX(-50%);
  width: 16px;
  height: 16px;
  border-radius: 50%;
  background-color: var(--sl-primary);
  border: 4px solid var(--sl-bg-body);
  z-index: 3;
}

/* Custom scrollbar for Webkit browsers */
.sl-horizontal-timeline-wrapper::-webkit-scrollbar {
  height: 8px;
}

.sl-horizontal-timeline-wrapper::-webkit-scrollbar-track {
  background: var(--sl-bg-body);
  border-radius: 10px;
}

.sl-horizontal-timeline-wrapper::-webkit-scrollbar-thumb {
  background: var(--sl-primary);
  border-radius: 10px;
  border: 2px solid var(--sl-bg-body);
}

.sl-horizontal-timeline-wrapper::-webkit-scrollbar-thumb:hover {
  background: var(--sl-accent);
}
